1	import { all } from '../db/index.js';
2	import type { Book } from './book.js';
3	import type { ReviewWithDetails } from './review.js';
4	
5	export interface RatedBook extends Book {
6	  avg_rating: number;
7	  review_count: number;
8	}
9	
10	const BOOK_SORT_COLUMNS: Record<string, string> = {
11	  title: 'title',
12	  author: 'author',
13	  year: 'published_year',
14	};
15	
16	// Books with at least `minReviews` reviews, best average first.
17	export function getTopRatedBooks(limit: number, minReviews: number): RatedBook[] {
18	  return all(`
19	    SELECT b.*, AVG(r.rating) AS avg_rating, COUNT(r.id) AS review_count
20	    FROM books b
21	    JOIN reviews r ON r.book_id = b.id
22	    GROUP BY b.id
23	    HAVING COUNT(r.id) >= ?
24	    ORDER BY avg_rating DESC, b.title
25	    LIMIT ?
26	  `, [minReviews, limit]) as unknown as RatedBook[];
27	}
28	
29	// Paginated catalogue. `page` starts at 1.
30	export function getBooksPage(page: number, pageSize: number, sortKey = 'title'): Book[] {
31	  const column = Object.hasOwn(BOOK_SORT_COLUMNS, sortKey) ? BOOK_SORT_COLUMNS[sortKey] : 'title';
32	  return all(
33	    `SELECT * FROM books ORDER BY ${column}, id LIMIT ? OFFSET ?`,
34	    [pageSize, (page - 1) * pageSize]
35	  ) as unknown as Book[];
36	}
37	
38	const REVIEW_SORTS: Record<string, string> = {
39	  newest: 'r.created_at DESC',
40	  oldest: 'r.created_at ASC',
41	  rating: 'r.rating DESC, r.created_at DESC',
42	};
43	
44	// Reviews for a book in one of the whitelisted orders.
45	export function getReviewsSorted(bookId: number, sortKey: string): ReviewWithDetails[] {
46	  const sort = Object.hasOwn(REVIEW_SORTS, sortKey) ? REVIEW_SORTS[sortKey] : REVIEW_SORTS.newest;
47	  return all(`
48	    SELECT r.*, u.username, u.display_name, b.title as book_title, b.author as book_author
49	    FROM reviews r
50	    JOIN users u ON r.user_id = u.id
51	    JOIN books b ON r.book_id = b.id
52	    WHERE r.book_id = ?
53	    ORDER BY ${sort}
54	  `, [bookId]) as unknown as ReviewWithDetails[];
55	}
56	
57	// Count of reviews per star value, always returning all five buckets.
58	export function getRatingHistogram(bookId: number): Record<number, number> {
59	  const rows = all(
60	    'SELECT rating, COUNT(*) AS n FROM reviews WHERE book_id = ? GROUP BY rating',
61	    [bookId]
62	  ) as unknown as { rating: number; n: number }[];
63	  const histogram: Record<number, number> = {};
64	  for (let star = 1; star <= 5; star++) histogram[star] = 0;
65	  for (const row of rows) histogram[row.rating] = row.n;
66	  return histogram;
67	}
